import { beforeAll, describe, expect, it, vi } from "vitest";

/**
 * Regression test for issue #120: Sections dashboard ignores grid_options on cards generated by streamline-card
 * https://github.com/brunosabot/streamline-card/issues/120
 *
 * Bug: In a sections view, Home Assistant reads `grid_options` from the config of
 * the card placed in the view (the streamline-card) and merges it with the
 * element's `getGridOptions()`. The `grid_options` defined in the template never
 * reached Home Assistant, so the default layout (12 columns) was always used.
 *
 * Expected: `getGridOptions()` returns the template's `grid_options`, on top of
 * the generated card's own grid options.
 */
vi.mock("../getLovelace-helper", () => ({
  getLovelace: () => ({
    config: {
      streamline_templates: {
        "no-grid-options-method": {
          card: {
            grid_options: { columns: 6, rows: "auto" },
            type: "custom:test-card-without-grid-options",
          },
        },
        "test-bubble": {
          card: {
            grid_options: { columns: 6, rows: "auto" },
            type: "custom:test-card",
          },
        },
        "without-grid-options": {
          card: { type: "custom:test-card" },
        },
      },
    },
  }),
  getLovelaceCast: () => null,
}));

class TestCard extends HTMLElement {
  setConfig(config) {
    this.config = config;
  }

  // Like most custom cards, it ignores `grid_options` from its own config
  getGridOptions() {
    return { columns: this.config.columns ?? 12, min_rows: 1, rows: 2 };
  }
}

const createStreamlineCard = (template) => {
  const card = document.createElement("streamline-card");
  card.setConfig({ template, type: "custom:streamline-card" });
  return card;
};

describe("Issue #120 - Sections dashboard ignores grid_options from the template", () => {
  beforeAll(async () => {
    customElements.define("test-card", TestCard);
    window.loadCardHelpers = () =>
      Promise.resolve({
        createCardElement: (config) => {
          if (config.type !== "custom:test-card") {
            // A plain element, without getGridOptions
            return document.createElement("div");
          }
          const element = document.createElement("test-card");
          element.setConfig(config);
          return element;
        },
      });

    await import("../streamline-card");
    await customElements.whenDefined("streamline-card");
  });

  it("should return the template grid_options over the card ones", () => {
    const card = createStreamlineCard("test-bubble");

    expect(card.getGridOptions()).toEqual({
      columns: 6,
      min_rows: 1,
      rows: "auto",
    });
  });

  it("should return the template grid_options when the card has no getGridOptions", () => {
    const card = createStreamlineCard("no-grid-options-method");

    expect(card.getGridOptions()).toEqual({ columns: 6, rows: "auto" });
  });

  it("should keep the card grid options when the template has none", () => {
    const card = createStreamlineCard("without-grid-options");

    expect(card.getGridOptions()).toEqual({
      columns: 12,
      min_rows: 1,
      rows: 2,
    });
  });
});
